91	 * @returns {number}
92	 */
93	export function lineVat(line) {
94	  const total = lineTotal(line);
95	  const discount = lineDiscount(line);
96	  const vatableAmount = total - discount;
97	  const vat = roundCents(vatableAmount * line.vatRate / 100);
