test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  const expectedVat = Math.round(47500 * 21 / 100);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 47500 + expectedVat);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
      { qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 47500 + 120000 + 3700;
  const expectedVat1 = Math.round(47500 * 21 / 100);
  const expectedVat2 = Math.round(120000 * 21 / 100);
  const expectedVat3 = Math.round(3700 * 9 / 100);
  const expectedVat = expectedVat1 + expectedVat2 + expectedVat3;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, expectedSubtotal + expectedVat);
});

