test('invoiceTotals with single discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 100000;
  const expectedDiscount = 10000;
  const expectedVat = Math.round((expectedSubtotal - expectedDiscount) * 21 / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount + expectedVat);
});

test('invoiceTotals with multiple discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 20000, discountPercent: 20, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 100000 + 100000;
  const expectedDiscount = 10000 + 20000;
  const expectedVat = Math.round((100000 - 10000) * 21 / 100) + Math.round((100000 - 20000) * 21 / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount + expectedVat);
});

