test('lineVat on discounted amount', () => {
  const line = { qty: 100, unitPrice: 10000, discountPercent: 10, vatRate: 21 };
  const vat = lineVat(line);
  const total = 100 * 10000;
  const discount = total * 10 / 100;
  const vatableAmount = total - discount;
  const expected = Math.round(vatableAmount * 21 / 100);
  assert.equal(vat, expected);
});

